use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn public_api_retries_transient_failures_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config(4, 10, 25), &mut sleeper, || {
        attempts += 1;
        if attempts == 3 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary outage".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn public_api_stops_at_attempt_budget_and_returns_last_error() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config(2, 5, 50), &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient(format!("failure {attempts}")))
    });

    assert_eq!(result, Err(RetryError::Transient("failure 2".into())));
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}

#[test]
fn zero_attempt_budget_still_makes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config(0, 1, 10), &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient("temporary".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("temporary".into())));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}

